type DestinationGroup = {
  title: string;
  href: string;
  links: { label: string; href: string; strong?: boolean }[];
};

const groups: DestinationGroup[] = [
  {
    title: "Europe",
    href: "/europe-tours",
    links: [
      { label: "Turkey Tours", href: "/d/turkey-tours" },
      { label: "Greece Tours", href: "/d/greece-tours" },
      { label: "Albania Tours", href: "/d/albania-tours" },
      { label: "Bulgaria Tours", href: "/d/bulgaria-tours" },
      { label: "All Europe Tours", href: "/europe-tours", strong: true },
    ],
  },
  {
    title: "America",
    href: "/d/north-america-tours",
    links: [
      { label: "United States Tours", href: "/d/united-states-tours" },
      { label: "Belize Tours", href: "/d/belize-tours" },
      { label: "Peru Tours", href: "/d/peru-tours" },
      { label: "Ecuador Tours", href: "/d/ecuador-tours" },
      { label: "Colombia Tours", href: "/d/colombia-tours" },
      { label: "North America Tours", href: "/north-america-tours", strong: true },
      { label: "South America Tours", href: "/south-america-tours", strong: true },
    ],
  },
  {
    title: "Asia",
    href: "/d/asia-tours",
    links: [
      { label: "Nepal Tours", href: "/d/nepal-tours" },
      { label: "Sri Lanka Tours", href: "/d/sri-lanka-tours" },
      { label: "Maldives Tours", href: "/d/maldives-tours" },
      { label: "Vietnam Tours", href: "/d/vietnam-tours" },
      { label: "All Asia Tours", href: "/asia-tours", strong: true },
    ],
  },
  {
    title: "Africa",
    href: "/d/africa-tours",
    links: [
      { label: "Tanzania Tours", href: "/d/tanzania-tours" },
      { label: "Egypt Tours", href: "/d/egypt-tours" },
      { label: "Uganda Tours", href: "/d/uganda-tours" },
      { label: "Kenya Tours", href: "/d/kenya-tours" },
      { label: "All Africa Tours", href: "/africa-tours", strong: true },
    ],
  },
];

export default function Destinations() {
  return (
    <section className="tw-py-12 md:tw-py-16 tw-font-display tw-bg-white">
      <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
        <div className="tw-text-center tw-mb-10">
          <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
            Explore tours by region
          </h2>
          <p className="tw-mt-1.5 tw-mb-0 tw-text-sm tw-text-[#6b6577]">
            Pick a destination and start planning your next adventure.
          </p>
        </div>

        <div className="tw-grid tw-grid-cols-1 sm:tw-grid-cols-2 lg:tw-grid-cols-4 tw-gap-5 lg:tw-gap-6">
          {groups.map((group) => (
            <div
              key={group.title}
              className="tw-rounded-2xl tw-bg-white tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6 hover:tw-border-[#d8d2e1] hover:tw-shadow-lg tw-transition-all tw-duration-200"
            >
              <a
                href={group.href}
                title={`${group.title} Tours`}
                className="tw-inline-block tw-text-[18px] tw-font-bold tw-text-[#14101c] tw-no-underline hover:tw-text-[#854ec9] tw-transition-colors"
              >
                {group.title}
              </a>
              <ul className="tw-mt-4 tw-space-y-1.5 tw-p-0 tw-m-0 tw-list-none">
                {group.links.map((link) => (
                  <li key={link.href + link.label}>
                    <a
                      href={link.href}
                      title={link.label}
                      className={`tw-no-underline tw-transition-colors hover:tw-text-[#854ec9] ${
                        link.strong
                          ? "tw-text-[14px] tw-font-semibold tw-text-[#14101c]"
                          : "tw-text-[14px] tw-text-[#5d556c]"
                      }`}
                    >
                      {link.label}
                    </a>
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
